INSERT INTO _teaser_card_plan (site_id, column_name, old_value, new_value, change_key, reason, premise, evidence) VALUES
    ('008ecaa5-ce9b-484d-9eb8-0f27659bc91d'::uuid, 'card_description', 'Caravans bound for northern India once passed this fortified desert outpost. It guarded trade routes from Multan toward Rajasthan, across a desert with hundreds of ancient settlement sites.', 'Once called Pholra, Fort Abbas guarded caravan routes across the Cholistan Desert, where hundreds of ancient settlements line a dry riverbed and the earliest finds are Hakra Ware.', 'teaser-card-s046-rollback:008ecaa5-ce9b-484d-9eb8-0f27659bc91d:card_description', 'rollback of teaser-card-s046: card_description ''Once called Pholra, Fort Abbas guarded caravan routes across the Cholistan Desert, where hundreds of ancient settlements line a dry riverbed and the earliest finds are Hakra Ware.'' restored on Fort Abbas', '399cc13dc594b36586134f62391a40f7666cb5d5e5a85dcb5b2902f19508612e|e65c587fcca2ba4b0a463c270a172ef47e15d96d50c6f11a15a8e6a9ffc9c3d4|e65c587fcca2ba4b0a463c270a172ef47e15d96d50c6f11a15a8e6a9ffc9c3d4', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-write-001", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Caravans bound for northern India once passed this fortified desert outpost. It guarded trade routes from Multan toward Rajasthan, across a desert with hundreds of ancient settlement sites."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "caravans travelling toward northern India once passed the place [S6]; it was a fortified outpost [S6]; the outpost lay in a desert [S7]; it guarded trade routes [S7]; the routes ran from Multan toward Rajasthan [S6]; the routes crossed a desert [S7]; hundreds of ancient settlement sites have been recorded in that desert [S2]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify-001 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Caravans once passed this outpost (Pholra/Phulra, now Fort Abbas), which stood on a trade route. [SUPPORTED: https://qjssh.com.pk/index.php/qjssh/article/download/209/188]; The caravans passing it were bound for northern India. [SUPPORTED: https://qjssh.com.pk/index.php/qjssh/article/download/209/188]; It was a fortified outpost. [SUPPORTED: https://aliusmanbaig.blogspot.com/2021/04/the-forty-seven-forts-of-ancient.html]; It is a desert outpost (in the Cholistan Desert). [SUPPORTED: https://en.wikipedia.org/wiki/Cholistan_Desert]; It guarded trade routes. [SUPPORTED: https://en.wikipedia.org/wiki/Cholistan_Desert]; The trade routes it guarded ran from Multan. [SUPPORTED: https://qjssh.com.pk/index.php/qjssh/article/download/209/188]; The trade routes it guarded ran toward Rajasthan. [SUPPORTED: https://aliusmanbaig.blogspot.com/2021/04/the-forty-seven-forts-of-ancient.html]; The routes crossed a desert with hundreds of ancient settlement sites. [SUPPORTED: https://en.wikipedia.org/wiki/Cholistan_Desert]"}]'::jsonb),
    ('01704ebd-c0b1-4c2b-bdd0-7ffb3b6b4370'::uuid, 'card_description', 'A giant, local legend says, made this mound on the way to fill a narrow ford. An estimated 22,000 cubic metres of earth went into the mound, the largest burial mound on its island.', 'Local legend says a giant, carrying clay to fill a narrow ford, lost it on the way. Near Sagard it rises still: the Dobberworth, about 15 metres tall, the largest tumulus on Rügen.', 'teaser-card-s046-rollback:01704ebd-c0b1-4c2b-bdd0-7ffb3b6b4370:card_description', 'rollback of teaser-card-s046: card_description ''Local legend says a giant, carrying clay to fill a narrow ford, lost it on the way. Near Sagard it rises still: the Dobberworth, about 15 metres tall, the largest tumulus on Rügen.'' restored on Dobberworth', '9959f455911cb95255f2cc07b3ac6639fe5da0c582f2d654f0fce3df7edf9e8e|14f686fc22e287143ea6317279bd50ae5d0d6146af4556f725efc7b8138cb0fc|14f686fc22e287143ea6317279bd50ae5d0d6146af4556f725efc7b8138cb0fc', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-rewrite-v-001", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "A giant, local legend says, made this mound on the way to fill a narrow ford. An estimated 22,000 cubic metres of earth went into the mound, the largest burial mound on its island."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-v-001 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "according to local legend, a giant made the mound [S4]; in the legend the giant was on the way to fill a narrow ford [S4]; an estimated 22,000 cubic metres of earth went into the mound [S2]; it is a burial mound (tumulus) [S1, S2]; it is the largest burial mound on its island [S1, S2]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify2-001 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "A giant, local legend says, made this mound [SUPPORTED: http://www.zeno.org/Literatur/M/Temme,+Jodocus+Deodatus+Hubertus/Sagen/Die+Volkssagen+von+Pommern+und+R%C3%BCgen/Die+Volkssagen+von+Pommern+und+R%C3%BCgen/190.+Der+Dubberworth]; The giant made it on the way to fill a narrow ford [SUPPORTED: http://www.zeno.org/Literatur/M/Temme,+Jodocus+Deodatus+Hubertus/Sagen/Die+Volkssagen+von+Pommern+und+R%C3%BCgen/Die+Volkssagen+von+Pommern+und+R%C3%BCgen/190.+Der+Dubberworth]; An estimated 22,000 cubic metres of earth went into the mound [SUPPORTED: https://www.auf-nach-mv.de/reiseziele/a-dobberworth-hue]; The mound is a burial mound and stands on an island [SUPPORTED: https://www.auf-nach-mv.de/reiseziele/a-dobberworth-hue]; The mound is the largest burial mound on its island [SUPPORTED: https://www.auf-nach-mv.de/reiseziele/a-dobberworth-hue]"}]'::jsonb),
    ('01dee6c5-2bcd-4fe7-9126-755ea3c7a3f7'::uuid, 'card_description', 'Submerged walls were first noted here in 1904 by the geologist Fokion Negris. The site is unique in having an almost complete town plan, including streets, buildings and tombs.', 'In Vatika Bay, Pavlopetri keeps an almost complete town plan: at least 15 buildings lie in 3 to 4 metres of water, the town believed submerged by an earthquake around 1000 BCE.', 'teaser-card-s046-rollback:01dee6c5-2bcd-4fe7-9126-755ea3c7a3f7:card_description', 'rollback of teaser-card-s046: card_description ''In Vatika Bay, Pavlopetri keeps an almost complete town plan: at least 15 buildings lie in 3 to 4 metres of water, the town believed submerged by an earthquake around 1000 BCE.'' restored on Pavlopetri', '8abd05aa889d97d7aadcac2ee36019df358f1df7adf7a97410c92eb77da5fce1|ad85dbae852399e7e4130602c07da65473e935a3af4253bcbd0e8185f58f46f0|ad85dbae852399e7e4130602c07da65473e935a3af4253bcbd0e8185f58f46f0', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-rewrite-v-001", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Submerged walls were first noted here in 1904 by the geologist Fokion Negris. The site is unique in having an almost complete town plan, including streets, buildings and tombs."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-v-001 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "there are submerged walls at the site [S3]; the walls were first noted in 1904 [S3]; they were noted by the geologist Fokion Negris [S3]; the site is unique in having an almost complete town plan [S2]; the town plan includes streets, buildings and tombs [S2]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify2-001 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Submerged walls were first noted here in 1904 [SUPPORTED: https://www.ancientportsantiques.com/wp-content/uploads/Documents/PLACES/GreecePeloponnesus/Pavlopetri-Gallou2012.pdf]; They were first noted by Fokion Negris [SUPPORTED: https://www.ancientportsantiques.com/wp-content/uploads/Documents/PLACES/GreecePeloponnesus/Pavlopetri-Gallou2012.pdf]; Fokion Negris was a geologist [SUPPORTED: https://www.ancientportsantiques.com/wp-content/uploads/Documents/PLACES/GreecePeloponnesus/Pavlopetri-Gallou2012.pdf]; The site is a submerged town [SUPPORTED: https://www.nottingham.ac.uk/pavlopetri/background.aspx]; The site is unique in having an almost complete town plan [SUPPORTED: https://www.sciencedaily.com/releases/2009/10/091016101809.htm]; The town plan includes streets, buildings and tombs [SUPPORTED: https://www.nottingham.ac.uk/pavlopetri/projectoverview2009-2013.aspx]"}]'::jsonb),
    ('0386a5a3-8842-4da8-ba7c-13e5fbcb46a0'::uuid, 'card_description', 'Just under 135 kilometres long, this Roman frontier dates to the late 1st century AD. From Rottweil in the southwest, the frontier runs northeast to Heidenheim, known in Latin as Aquileia.', 'Across the Swabian Alb runs the Alb Limes, a Roman frontier of the late 1st century AD, stretching just under 135 kilometres from Rottweil in the southwest to Heidenheim an der Brenz.', 'teaser-card-s046-rollback:0386a5a3-8842-4da8-ba7c-13e5fbcb46a0:card_description', 'rollback of teaser-card-s046: card_description ''Across the Swabian Alb runs the Alb Limes, a Roman frontier of the late 1st century AD, stretching just under 135 kilometres from Rottweil in the southwest to Heidenheim an der Brenz.'' restored on Alb Limes', '161db07cba5d2fba6b8ef61aa79e51140727db188d930a021b3f56a19d93ae67|72e8a0cc53463216b47100f2c5135f7a751e8d2c4231fe08d84de984e8e64380|72e8a0cc53463216b47100f2c5135f7a751e8d2c4231fe08d84de984e8e64380', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-rewrite1-001", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Just under 135 kilometres long, this Roman frontier dates to the late 1st century AD. From Rottweil in the southwest, the frontier runs northeast to Heidenheim, known in Latin as Aquileia."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check1-001 (check1), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "the frontier is just under 135 kilometres long [S2]; it is a Roman frontier [S1]; it dates to the late 1st century AD [S1]; it starts at Rottweil in the southwest [S2]; it runs northeast to Heidenheim [S2]; Heidenheim is known in Latin as Aquileia [S2]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify-001 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "This frontier (the Alb Limes) runs from Rottweil to Heidenheim. [SUPPORTED: http://www.biosphaere-alb.com/Archiv/06_03/20_alblimes.htm]; It is a Roman frontier. [SUPPORTED: https://de.wikipedia.org/wiki/Alblimes]; It is just under 135 kilometres long. [SUPPORTED: https://de.wikipedia.org/wiki/Alblimes]; It dates to the late 1st century AD. [SUPPORTED: http://www.biosphaere-alb.com/Archiv/06_03/20_alblimes.htm]; Rottweil lies at its southwestern end. [SUPPORTED: https://de.wikipedia.org/wiki/Alblimes]; It runs northeast to Heidenheim. [SUPPORTED: https://de.wikipedia.org/wiki/Alblimes]; Heidenheim was known in Latin as Aquileia. [SUPPORTED: https://de.wikipedia.org/wiki/Alblimes]"}]'::jsonb),
    ('082935cc-6367-40a7-86e5-dd01e0be5b1c'::uuid, 'card_description', 'A photograph from 1908 shows sixteen stones in this circle. By 1964 the count had grown to twenty-eight, yet the original oval had eight or possibly nine sockets.', 'The stones of Hampton Down Stone Circle were not in their original position. A May 1965 excavation found the original oval circle a few feet to the west, on a ridge 680 feet above sea level.', 'teaser-card-s046-rollback:082935cc-6367-40a7-86e5-dd01e0be5b1c:card_description', 'rollback of teaser-card-s046: card_description ''The stones of Hampton Down Stone Circle were not in their original position. A May 1965 excavation found the original oval circle a few feet to the west, on a ridge 680 feet above sea level.'' restored on Hampton Down Stone Circle', '2d29c910bfccaa8b4e9eb520e94814ef558e7cc9e73942a5641a8cb19d1c7535|60a46c22db450d72b4d0ffa4692e55ec0acc79eb50bca60822c167fd68aed168|60a46c22db450d72b4d0ffa4692e55ec0acc79eb50bca60822c167fd68aed168', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-write-001", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "A photograph from 1908 shows sixteen stones in this circle. By 1964 the count had grown to twenty-eight, yet the original oval had eight or possibly nine sockets."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "a photograph from 1908 shows sixteen stones in the circle [S2]; by 1964 twenty-eight stones were counted as part of the circle [S3]; the original circle was oval [S8]; the original circle had eight or possibly nine stone sockets [S8]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify-002 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "A photograph from 1908 shows sixteen stones in this circle [SUPPORTED: https://dorset-nl.org.uk/location/hampton_down_stone_circle/]; By 1964 the count had grown to twenty-eight [SUPPORTED: https://dorset-nl.org.uk/location/hampton_down_stone_circle/]; The original circle was an oval [SUPPORTED: https://heritage.dorsetcouncil.gov.uk/Monument/MDO2066]; The original oval had eight or possibly nine sockets [SUPPORTED: https://heritage.dorsetcouncil.gov.uk/Monument/MDO2066]"}]'::jsonb),
    ('09fcbc60-19c1-4742-a69d-3cb7afe19443'::uuid, 'card_description', 'In 1939, all eighteen stones of this circle lay on the ground. Yet a record says that in 1815, one stone on the ring''s southern side was still standing upright.', 'Kingston Russell Stone Circle, the largest surviving in Dorset, has never been excavated. In 1815 one of its stones still stood upright; by 1939 all of them lay on the ground.', 'teaser-card-s046-rollback:09fcbc60-19c1-4742-a69d-3cb7afe19443:card_description', 'rollback of teaser-card-s046: card_description ''Kingston Russell Stone Circle, the largest surviving in Dorset, has never been excavated. In 1815 one of its stones still stood upright; by 1939 all of them lay on the ground.'' restored on Kingston Russell Stone Circle', '1227d3c03cd5aec0da207afccaa660671f47b8d09987d8bcfaf109068b2abb16|e4cc5376d7761ea94c36080ace884dde177213ba26e9622f77e1521a9e76d6ef|e4cc5376d7761ea94c36080ace884dde177213ba26e9622f77e1521a9e76d6ef', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-write-001", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "In 1939, all eighteen stones of this circle lay on the ground. Yet a record says that in 1815, one stone on the ring''s southern side was still standing upright."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "as of 1939 all the stones of the circle lay on the ground [S8]; the circle has eighteen stones [S7]; a record says that in 1815 one stone was still standing upright [S8]; that stone was on the ring''s southern side [S8]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify-002 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "In 1939, all the stones of this circle lay on the ground [SUPPORTED: https://heritage.dorsetcouncil.gov.uk/Monument/MDO1264]; The circle has eighteen stones [SUPPORTED: https://heritage.dorsetcouncil.gov.uk/Monument/MDO1264]; A record of the circle from 1815 exists [SUPPORTED: https://heritage.dorsetcouncil.gov.uk/Monument/MDO1264]; In 1815 one stone was still standing upright [SUPPORTED: https://heritage.dorsetcouncil.gov.uk/Monument/MDO1264]; The stone still standing in 1815 was on the ring''s southern side [SUPPORTED: https://heritage.dorsetcouncil.gov.uk/Monument/MDO1264]"}]'::jsonb),
    ('0c879c8d-da82-4297-be35-796650ca0765'::uuid, 'card_description', 'A Roman road called Sarn Helen can be traced right across this common. On its northern tip, an Iron Age hillfort sits atop a grassy mound above the valley of the River Usk.', 'Across the plateau of Mynydd Illtud the Roman road Sarn Helen can still be traced, while on the grassy mound of Twyn y Gaer an Iron Age hillfort overlooks the valley of the River Usk.', 'teaser-card-s046-rollback:0c879c8d-da82-4297-be35-796650ca0765:card_description', 'rollback of teaser-card-s046: card_description ''Across the plateau of Mynydd Illtud the Roman road Sarn Helen can still be traced, while on the grassy mound of Twyn y Gaer an Iron Age hillfort overlooks the valley of the River Usk.'' restored on Mynydd Illtud', '82bc74c37b18d868e7fd86a0d32f2c62fd88b56636b6b4d7ab7d1a88dab44eb2|725ac1f10f5ea50e7f574a54516196abf994c48017428bdf69389f45142c174e|725ac1f10f5ea50e7f574a54516196abf994c48017428bdf69389f45142c174e', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-write-001", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "A Roman road called Sarn Helen can be traced right across this common. On its northern tip, an Iron Age hillfort sits atop a grassy mound above the valley of the River Usk."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "a Roman road runs across the common [S7]; the road is called Sarn Helen [S7]; its course can be traced across the common [S7]; an Iron Age hillfort is on the common''s northern tip [S5]; the hillfort sits atop a grassy mound [S5]; the hillfort overlooks the valley of the River Usk [S3, S4]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify-002 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "A Roman road called Sarn Helen runs across this common [SUPPORTED: https://en.wikipedia.org/wiki/Sarn_Helen]; The road can be traced on the ground right across the common [SUPPORTED: https://coflein.gov.uk/en/site/275632/]; An Iron Age hillfort sits on the northern tip of the common [SUPPORTED: https://www.fforestfawrgeopark.org.uk/enjoying/places-to-go/classic-beacons/mynydd-illtud-and-traeth-mawr/]; The hillfort sits atop a mound [SUPPORTED: https://coflein.gov.uk/en/sites/305069]; The mound is grassy [SUPPORTED: https://coflein.gov.uk/en/sites/305069]; The hillfort is above the valley of the River Usk [SUPPORTED: https://coflein.gov.uk/en/sites/305069]"}]'::jsonb),
    ('116de084-cd63-4ec0-aeca-4702b91b1bdb'::uuid, 'card_description', 'A road called the Military Road cuts this Roman fort in two. When the field north of the road, holding the fort''s northern part, was first ploughed in 1827, a fine bath-house was found.', 'The Military Road now cuts through Hunnum, the fifth fort on Hadrian''s Wall, built between 122 and 126 AD. A slab from its west gate names the Legio VI Victrix as its first builders.', 'teaser-card-s046-rollback:116de084-cd63-4ec0-aeca-4702b91b1bdb:card_description', 'rollback of teaser-card-s046: card_description "The Military Road now cuts through Hunnum, the fifth fort on Hadrian''s Wall, built between 122 and 126 AD. A slab from its west gate names the Legio VI Victrix as its first builders." restored on Hunnum', '6faff4e8632fe948a3871ad0feeae6f3e20846e12a34be0bfa640b4e295e223a|7f408053af8a83757589da092268f44e0479da4e290ea4ca9a55c44b6062a925|7f408053af8a83757589da092268f44e0479da4e290ea4ca9a55c44b6062a925', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-rewrite1-001", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "A road called the Military Road cuts this Roman fort in two. When the field north of the road, holding the fort''s northern part, was first ploughed in 1827, a fine bath-house was found."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check1-001 (check1), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "the Military Road cuts the fort in two [S3]; it is a Roman fort [S1]; the field north of the road holds the fort''s northern part [S8]; that field was first ploughed in 1827 [S8]; a fine bath-house was found then [S8]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify-003 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "A road cuts this Roman fort (Hunnum / Halton Chesters on Hadrian''s Wall) in two [SUPPORTED: https://keystothepast.info/search-records/results-of-search/results-of-search-2/site-details/?PRN=N8635]; The road that cuts the fort is called the Military Road [SUPPORTED: https://perlineamvalli.wordpress.com/tag/halton-chesters/]; It is a Roman fort [SUPPORTED: https://keystothepast.info/search-records/results-of-search/results-of-search-2/site-details/?PRN=N8635]; The field north of the road holds the fort''s northern part [SUPPORTED: https://perlineamvalli.wordpress.com/tag/halton-chesters/]; That field was first ploughed in 1827 [SUPPORTED: https://keystothepast.info/search-records/results-of-search/results-of-search-2/site-details/?PRN=N8635]; When the field was first ploughed, a fine bath-house was found [SUPPORTED: https://perlineamvalli.wordpress.com/tag/halton-chesters/]"}]'::jsonb),
    ('118c6bd0-cfa1-4376-8f42-34e75bec43d3'::uuid, 'card_description', 'Five burial cairns and two more stones sit inside one stone circle here. Around 42 stones form that irregular ring, the largest of five stone circles about 4,000 years old.', 'On the slopes of Boat How lie the Burnmoor Stone Circles, approximately 4,000 years old. In the largest, Brat''s Hill, around 42 stones ring five funerary cairns and two further stones.', 'teaser-card-s046-rollback:118c6bd0-cfa1-4376-8f42-34e75bec43d3:card_description', 'rollback of teaser-card-s046: card_description "On the slopes of Boat How lie the Burnmoor Stone Circles, approximately 4,000 years old. In the largest, Brat''s Hill, around 42 stones ring five funerary cairns and two further stones." restored on Burnmoor Stone Circles', 'e494a9bf0bc1798faae61a0323c8b00066ca985e084b4ec70ff736f61befce91|5f31c7c9151b74a8c8c75c28994ae7e592a53d1339d22ad5f4b85bda3bd6a7e3|5f31c7c9151b74a8c8c75c28994ae7e592a53d1339d22ad5f4b85bda3bd6a7e3', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-write-002", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Five burial cairns and two more stones sit inside one stone circle here. Around 42 stones form that irregular ring, the largest of five stone circles about 4,000 years old."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-002 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "five funerary cairns lie inside one of the stone circles [S5]; two further stones lie inside that circle [S5]; that circle is formed by around 42 stones [S4]; that circle is irregular [S4]; it is the largest of the site''s stone circles [S3, S4]; the site has five stone circles [S1]; the circles are about 4,000 years old [S1]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify-003 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Five cairns sit inside one stone circle here (Brat''s Hill, the Burnmoor stone circles, Cumbria, England) [SUPPORTED: https://www.megalithic.co.uk/article.php?sid=23]; The cairns inside the circle are burial cairns [SUPPORTED: https://lingregory.substack.com/p/sacred-sites-brats-hill-stone-circle]; Two more stones sit inside the circle besides the cairns [SUPPORTED: https://de.wikipedia.org/wiki/Steinkreise_im_Burnmoor]; Around 42 stones form that ring [SUPPORTED: https://www.megalithic.co.uk/article.php?sid=23]; The ring is irregular [SUPPORTED: https://www.megalithic.co.uk/article.php?sid=23]; It is the largest of five stone circles here [SUPPORTED: https://www.megalithic.co.uk/article.php?sid=23]; The stone circles are about 4,000 years old [SUPPORTED: https://thehistorypress.co.uk/article/top-10-stone-circles-in-the-lake-district-national-park/]"}]'::jsonb),
    ('11aae1cf-691a-45a5-a873-e4ac938587b2'::uuid, 'card_description', 'Builders here moved from many-sided blocks to smooth cut stone. People lived at these ruins in Hellenistic, Roman and Byzantine times, and the last of those phases left a basilica.', '3rd century BC to 15th century AD -- Hellenistic, Roman, and Byzantine layers. Polygonal masonry in the oldest houses; smooth cut stone later. Cisterns, sarcophagi, and church ruins mark each era.', 'teaser-card-s046-rollback:11aae1cf-691a-45a5-a873-e4ac938587b2:card_description', 'rollback of teaser-card-s046: card_description ''3rd century BC to 15th century AD -- Hellenistic, Roman, and Byzantine layers. Polygonal masonry in the oldest houses; smooth cut stone later. Cisterns, sarcophagi, and church ruins mark each era.'' restored on Öküzlü Ören Yeri', '7ee75c6a1bbbef902805e4a47a8940150d03f1912de4e927ae794e6a3e90a993|7b1b9f4c9129ea10fb50424fad54166990043712fb27f198f46445babb761772|7b1b9f4c9129ea10fb50424fad54166990043712fb27f198f46445babb761772', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-rewrite2-001", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Builders here moved from many-sided blocks to smooth cut stone. People lived at these ruins in Hellenistic, Roman and Byzantine times, and the last of those phases left a basilica."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check2-001 (check2), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "the oldest surviving structures were built of polygonal (many-sided) blocks [S3]; later constructions used smooth cut stone [S3]; the site was occupied in Hellenistic times [S2]; the site was occupied in Roman times [S2]; the site was occupied in Byzantine times [S2]; the Byzantine phase left a basilica [S2]; the site is ruins [S1]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify-003 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Builders here (the ruins of Öküzlü, Mersin, Türkiye) moved from one way of building to another [SUPPORTED: https://tr.wikipedia.org/wiki/%C3%96k%C3%BCzl%C3%BC_(antik_kent)]; The earlier builders used many-sided (polygonal) blocks [SUPPORTED: https://de.wikipedia.org/wiki/%C3%96k%C3%BCzl%C3%BC]; The later builders used smooth cut stone [SUPPORTED: https://tr.wikipedia.org/wiki/%C3%96k%C3%BCzl%C3%BC_(antik_kent)]; People lived at these ruins in Hellenistic times [SUPPORTED: https://okuldisiogrenme.eba.gov.tr/mekan-detay/okuzlu-oren-yeri-9011]; People lived at these ruins in Roman times [SUPPORTED: https://okuldisiogrenme.eba.gov.tr/mekan-detay/okuzlu-oren-yeri-9011]; People lived at these ruins in Byzantine times [SUPPORTED: https://de.wikipedia.org/wiki/%C3%96k%C3%BCzl%C3%BC]; There is a basilica at the site [SUPPORTED: https://okuldisiogrenme.eba.gov.tr/mekan-detay/okuzlu-oren-yeri-9011]; The basilica was left by the last (Byzantine) phase [SUPPORTED: https://de.wikipedia.org/wiki/%C3%96k%C3%BCzl%C3%BC]"}]'::jsonb),
    ('126756cf-1651-49dd-8075-11e19248b37f'::uuid, 'card_description', 'Remains of a golden man were found here in 2003. Numerous Early Saka burial mounds were found in this valley, and the mounds contained vast quantities of precious golden jewellery.', 'In the Shilikty Valley of eastern Kazakhstan, Early Saka kurgans held vast quantities of golden jewelry, and in 2003 the remains of a "golden man" were found with 4262 gold finds.', 'teaser-card-s046-rollback:126756cf-1651-49dd-8075-11e19248b37f:card_description', 'rollback of teaser-card-s046: card_description ''In the Shilikty Valley of eastern Kazakhstan, Early Saka kurgans held vast quantities of golden jewelry, and in 2003 the remains of a "golden man" were found with 4262 gold finds.'' restored on Shilikty', '7176d6a760aa209c0f1d6e8e73b5d239bbd0df3451fe807a5be76e1e649a0535|de30285e3dedda519c5e975cf727e094d19c3b68e691513b4433f2705d2727e3|de30285e3dedda519c5e975cf727e094d19c3b68e691513b4433f2705d2727e3', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-rewrite-v-001", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Remains of a golden man were found here in 2003. Numerous Early Saka burial mounds were found in this valley, and the mounds contained vast quantities of precious golden jewellery."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-v-001 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "remains of a golden man were found at the site [S5]; they were found in 2003 [S5]; numerous burial mounds (kurgans) were found at the site [S2]; the mounds are Early Saka [S2]; the site lies in a valley [S1]; the mounds contained vast quantities of precious golden jewellery [S4]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify2-001 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Remains of a golden man were found here [SUPPORTED: https://rupkatha.com/V12/n6/v12n621.pdf]; The remains found here are those of a \"golden man\" [SUPPORTED: https://rupkatha.com/V12/n6/v12n621.pdf]; The golden man was found in 2003 [SUPPORTED: https://par.nsf.gov/servlets/purl/10343013]; Numerous burial mounds were found in this valley [SUPPORTED: https://par.nsf.gov/servlets/purl/10343013]; The burial mounds are Early Saka [SUPPORTED: https://par.nsf.gov/servlets/purl/10343013]; The mounds contained vast quantities of precious golden jewellery [SUPPORTED: https://rupkatha.com/V12/n6/v12n621.pdf]"}]'::jsonb),
    ('171c0658-fbad-43fd-9764-fa7b37c5ba28'::uuid, 'card_description', 'A pit about 1 metre deep and one flint flake turned up in this stone chamber. Above it, two upright stones hold a capstone whose hollows may be cup marks, or may be natural.', 'Near a hilltop overlooking Goonhilly Downs, upright stones hold the capstone of the Three Brothers of Grugith, a Neolithic dolmen; its hollows may be cup marks, or may be natural.', 'teaser-card-s046-rollback:171c0658-fbad-43fd-9764-fa7b37c5ba28:card_description', 'rollback of teaser-card-s046: card_description ''Near a hilltop overlooking Goonhilly Downs, upright stones hold the capstone of the Three Brothers of Grugith, a Neolithic dolmen; its hollows may be cup marks, or may be natural.'' restored on Three Brothers of Grugith', '6fc323ee9b6210aa4deb8e0b5db48b8c3ce99940f0d0ed2b3685a5461edfcd57|e0ee99ba5f958a6f4ba33208ccc0387d9761605fd86a489103ced4bc7d12ae8f|e0ee99ba5f958a6f4ba33208ccc0387d9761605fd86a489103ced4bc7d12ae8f', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-write-003", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "A pit about 1 metre deep and one flint flake turned up in this stone chamber. Above it, two upright stones hold a capstone whose hollows may be cup marks, or may be natural."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-003 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "a pit about 1 metre deep was found in the chamber [S6]; one flint flake was found in the chamber [S6]; the site is a chamber enclosed by stones [S5]; two upright stones support a capstone [S4]; the capstone has hollows that may be cup marks or may be natural (hedged) [S4]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify-005 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "A pit about 1 metre deep turned up in this stone chamber [SUPPORTED: https://cornishbirdblog.com/the-three-brothers-of-grugwith/]; One flint flake turned up in this stone chamber [SUPPORTED: https://cornishbirdblog.com/the-three-brothers-of-grugwith/]; Two upright stones hold a capstone above the chamber [SUPPORTED: https://cornishbirdblog.com/the-three-brothers-of-grugwith/]; The capstone has hollows [SUPPORTED: https://cornishbirdblog.com/the-three-brothers-of-grugwith/]; The capstone''s hollows may be cup marks, or may be natural [SUPPORTED: https://cornishbirdblog.com/the-three-brothers-of-grugwith/]"}]'::jsonb),
    ('18ab996a-0aea-4f62-bd8d-3461adda0c88'::uuid, 'card_description', 'Granite blocks pile up on this ridge, recalling the Cheesewring. Prehistoric monuments stand among the rocks, and the outcrop was thought to have been a religious focal point.', 'On Bodmin Moor, Showery Tor''s erosion-shaped granite blocks are thought to have been a religious focal point, possibly Neolithic or Bronze Age; no dig is recorded. Were burials made here?', 'teaser-card-s046-rollback:18ab996a-0aea-4f62-bd8d-3461adda0c88:card_description', 'rollback of teaser-card-s046: card_description "On Bodmin Moor, Showery Tor''s erosion-shaped granite blocks are thought to have been a religious focal point, possibly Neolithic or Bronze Age; no dig is recorded. Were burials made here?" restored on Showery Tor', '67d0090493d4a19800ead6d47020f5afa660725999a82bf06e832f7e957e55f0|e0d78c09f910705a9b2a6249f4a4feab0f8d2d685140a6dfeaba24025c3c6c5d|e0d78c09f910705a9b2a6249f4a4feab0f8d2d685140a6dfeaba24025c3c6c5d', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-write-003", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Granite blocks pile up on this ridge, recalling the Cheesewring. Prehistoric monuments stand among the rocks, and the outcrop was thought to have been a religious focal point."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-003 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "the outcrop is made of granite blocks [S5]; it lies on a ridge [S1]; it is reminiscent of the Cheesewring [S5]; there are prehistoric monuments at the site [S2]; the site was thought to have been a religious focal point (hedged) [S3]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify-005 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Blocks pile up on this ridge [SUPPORTED: https://www.intocornwall.com/engine/azabout.asp?guide=Showery+Tor]; The blocks are granite [SUPPORTED: https://www.intocornwall.com/engine/azabout.asp?guide=Showery+Tor]; The granite pile recalls the Cheesewring [SUPPORTED: https://www.intocornwall.com/engine/azabout.asp?guide=Showery+Tor]; Prehistoric monuments stand among the rocks [SUPPORTED: https://www.iwalkcornwall.co.uk/pi/showery_tor]; The outcrop was thought to have been a religious focal point [SUPPORTED: https://www.iwalkcornwall.co.uk/pi/showery_tor]"}]'::jsonb),
    ('190fd91a-8c04-4665-9121-b89eff26130f'::uuid, 'card_description', 'A capstone shaped like a wedge rests on upright stones in a farmer''s field. The stones are the central chamber of a Neolithic passage grave, of a type more often found in Ireland.', 'In a farmer''s field on Anglesey, three upright stones of Bodowyr Burial Chamber hold up a robust, wedge-shaped capstone. In 1833 four were said to hold it: one seems to have fallen since.', 'teaser-card-s046-rollback:190fd91a-8c04-4665-9121-b89eff26130f:card_description', 'rollback of teaser-card-s046: card_description "In a farmer''s field on Anglesey, three upright stones of Bodowyr Burial Chamber hold up a robust, wedge-shaped capstone. In 1833 four were said to hold it: one seems to have fallen since." restored on Bodowyr Burial Chamber', 'd0b497dfbcdf1c20acf115d15153b246208e2e0cbbf35560955386d82f07240c|a681d648ccb56a845619f0adc3b3aad145c59a20d0824e5b6578a3e1afe436c6|a681d648ccb56a845619f0adc3b3aad145c59a20d0824e5b6578a3e1afe436c6', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-write-003", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "A capstone shaped like a wedge rests on upright stones in a farmer''s field. The stones are the central chamber of a Neolithic passage grave, of a type more often found in Ireland."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-003 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "the capstone is wedge-shaped [S7]; the capstone rests on upright stones [S7]; the monument stands in a farmer''s field [S1]; the stones are the central chamber of a passage grave [S6]; it is Neolithic [S1]; the passage grave is of a type more often found in Ireland [S6]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify-005 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "A capstone shaped like a wedge (the identifying feature of the site). [SUPPORTED: http://www.stone-circles.org.uk/stone/bodowyr.htm]; The capstone rests on upright stones. [SUPPORTED: https://cadwpublic-api.azurewebsites.net/reports/sam/FullReport?lang=&id=2505]; The stones stand in a farmer''s field. [SUPPORTED: http://www.stone-circles.org.uk/stone/bodowyr.htm]; The stones are the central chamber of a passage grave. [SUPPORTED: http://www.stone-circles.org.uk/stone/bodowyr.htm]; The passage grave is Neolithic. [SUPPORTED: https://cadwpublic-api.azurewebsites.net/reports/sam/FullReport?lang=&id=2505]; The passage grave is of a type more often found in Ireland. [SUPPORTED: http://www.stone-circles.org.uk/stone/bodowyr.htm]"}]'::jsonb),
    ('1ab97e76-933a-4dc5-a734-42f53c8c7667'::uuid, 'card_description', 'Richard Reiss found fallen stones of this ring again in 1965. He measured a double oval of sarsen megaliths, but those stones were later removed while a motorway was built.', 'Fir Clump Stone Circle in Burderop Wood was a double oval ring of sarsen megaliths, levelled around the 1860s. Some rediscovered in 1965 were removed in 1969 during construction of the M4.', 'teaser-card-s046-rollback:1ab97e76-933a-4dc5-a734-42f53c8c7667:card_description', 'rollback of teaser-card-s046: card_description ''Fir Clump Stone Circle in Burderop Wood was a double oval ring of sarsen megaliths, levelled around the 1860s. Some rediscovered in 1965 were removed in 1969 during construction of the M4.'' restored on Fir Clump Stone Circle', '74cbced100b8713665b4d53febf18a068ff95a140025742ce98ba660628d6683|9caf89ba21e2aed8875568f0b7382f8d32de5548b61de9e348aab9e08cfafd0d|9caf89ba21e2aed8875568f0b7382f8d32de5548b61de9e348aab9e08cfafd0d', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-write-003", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Richard Reiss found fallen stones of this ring again in 1965. He measured a double oval of sarsen megaliths, but those stones were later removed while a motorway was built."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-003 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Richard Reiss rediscovered fallen stones of the ring [S7]; this happened in 1965 [S7]; the monument is a ring of stones [S1, S2]; Reiss measured the monument [S7]; the monument was a double oval [S3]; it was made of sarsen megaliths [S3]; those stones were later removed during the construction of a motorway [S8]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify-005 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Richard Reiss found stones of this ring again in 1965. [SUPPORTED: https://www.megalithic.co.uk/article.php?sid=3236]; The stones he found were fallen. [SUPPORTED: https://www.megalithic.co.uk/article.php?sid=3236]; He measured the ring. [SUPPORTED: https://www.megalithic.co.uk/article.php?sid=3236]; The ring was double. [SUPPORTED: https://www.megalithic.co.uk/article.php?sid=3236]; The ring was oval. [SUPPORTED: https://www.megalithic.co.uk/article.php?sid=3236]; The megaliths were sarsens. [SUPPORTED: https://www.megalithic.co.uk/article.php?sid=3236]; Those stones were later removed. [SUPPORTED: https://www.megalithic.co.uk/article.php?sid=3236]; They were removed while a motorway was built. [SUPPORTED: https://www.megalithic.co.uk/article.php?sid=3236]"}]'::jsonb),
    ('1cc5420b-1545-470c-bff0-dacfea7ec800'::uuid, 'card_description', 'No evidence names the person this Greek cliff tomb was built for. Clearly visible across the plain, the tomb must have been made for someone of high rank in the late sixth century BC.', 'A late sixth-century BC Greek rock-tomb cut into a cliff near Marj, Al-Mnaykhrat is clearly visible across the plain. It was made for someone of high rank, yet no evidence tells us who.', 'teaser-card-s046-rollback:1cc5420b-1545-470c-bff0-dacfea7ec800:card_description', 'rollback of teaser-card-s046: card_description ''A late sixth-century BC Greek rock-tomb cut into a cliff near Marj, Al-Mnaykhrat is clearly visible across the plain. It was made for someone of high rank, yet no evidence tells us who.'' restored on Al-Mnaykhrat', 'add0004fef4a0c7ebbff41aaa5c0e8a254f69686c7866120017ade27fec83b39|93a32dee90118da7222954ccffd7e4ce736dbf8f2456ef595dee9d5420925f10|93a32dee90118da7222954ccffd7e4ce736dbf8f2456ef595dee9d5420925f10', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-write-003", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "No evidence names the person this Greek cliff tomb was built for. Clearly visible across the plain, the tomb must have been made for someone of high rank in the late sixth century BC."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-003 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "there is no evidence regarding the identity of the person the tomb was built for [S3]; it is a Greek tomb [S1]; the tomb is cut into a cliff [S2]; the tomb is clearly visible across the surrounding plain [S3]; the tomb must have been built for a high-ranking individual [S3]; it dates to the late sixth century BC [S1, S4]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify-00