    ('1d25e910-a12c-41a1-a7c9-caf4aa769fde'::uuid, 'card_description', 'Digs revealed 149 bags of pottery fragments at this residential site. It flourished in the era of the intermediate Arab kingdoms, with links to nearby Thaj, Failaka Island and Al-Faw.', '2nd-century BC residential complex near Jubail with water facilities, reception rooms, and storage. Occupied continuously from ~200 BC into the 3rd century AD in a strategically key locale.', 'teaser-card-s046-rollback:1d25e910-a12c-41a1-a7c9-caf4aa769fde:card_description', 'rollback of teaser-card-s046: card_description ''2nd-century BC residential complex near Jubail with water facilities, reception rooms, and storage. Occupied continuously from ~200 BC into the 3rd century AD in a strategically key locale.'' restored on Al-Dafi Site', '1ed8011637b8ee5e36ae3db99058427a2ea97f172045d2d40c8a822d03bedbca|91c83769f76148a173fefe820c7252a8b010944deb10686aaf02e41c9d967d2e|91c83769f76148a173fefe820c7252a8b010944deb10686aaf02e41c9d967d2e', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-rewrite-v-002", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Digs revealed 149 bags of pottery fragments at this residential site. It flourished in the era of the intermediate Arab kingdoms, with links to nearby Thaj, Failaka Island and Al-Faw."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-v-002 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "excavations revealed pottery fragments [S3]; the pottery fragments filled 149 bags [S3]; it is a residential site [S1]; it flourished during the era of the intermediate Arab kingdoms [S2]; the site has links to nearby Thaj [S4]; the site has links to Failaka Island [S4]; the site has links to Al-Faw [S4]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify2-00