    ('22f53fa2-6170-4d7b-ac52-5904861bb47c'::uuid, 'card_description', 'Over 100 herb species grow on this Bronze Age barrow cemetery. Its unimproved chalk grassland and rich insect life make it a protected site for science, looked after by a wildlife trust.', 'Seven Barrows is a Bronze Age barrow cemetery at Upper Lambourn in Berkshire, England. Its unimproved chalk grassland supports over 100 herb species and a rich insect fauna.', 'teaser-card-s046-rollback:22f53fa2-6170-4d7b-ac52-5904861bb47c:card_description', 'rollback of teaser-card-s046: card_description ''Seven Barrows is a Bronze Age barrow cemetery at Upper Lambourn in Berkshire, England. Its unimproved chalk grassland supports over 100 herb species and a rich insect fauna.'' restored on Seven Barrows', '666723a7ee54bac801862f24d47d5df051c3f6ebd2919776fae97c63a4e0cf78|9ac600fc7bb07c156b84c4749127c3551d79d6bd418cfff281b5ebaf4bd3830a|9ac600fc7bb07c156b84c4749127c3551d79d6bd418cfff281b5ebaf4bd3830a', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-write-004", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Over 100 herb species grow on this Bronze Age barrow cemetery. Its unimproved chalk grassland and rich insect life make it a protected site for science, looked after by a wildlife trust."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-004 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "over 100 herb species grow at the site [S2]; the site is a barrow cemetery [S1]; it dates to the Bronze Age [S1]; it has unimproved chalk grassland [S2]; it has rich insect life [S2]; these make it a protected site for science (biological SSSI) [S2]; it is looked after by a wildlife trust [S3]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify-006 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Over 100 herb species grow on this barrow cemetery [SUPPORTED: https://designatedsites.naturalengland.org.uk/PDFsForWeb/Citation/1003212.pdf]; It is a Bronze Age barrow cemetery [SUPPORTED: https://designatedsites.naturalengland.org.uk/PDFsForWeb/Citation/1003212.pdf]; It has unimproved chalk grassland [SUPPORTED: https://designatedsites.naturalengland.org.uk/PDFsForWeb/Citation/1003212.pdf]; It has rich insect life [SUPPORTED: https://designatedsites.naturalengland.org.uk/PDFsForWeb/Citation/1003212.pdf]; It is a protected site for science (Site of Special Scientific Interest) [SUPPORTED: https://designatedsites.naturalengland.org.uk/PDFsForWeb/Citation/1003212.pdf]; Its chalk grassland and insect life are what make it a protected site for science (reasons for notification) [SUPPORTED: https://designatedsites.naturalengland.org.uk/PDFsForWeb/Citation/1003212.pdf]; It is looked after by a wildlife trust [SUPPORTED: https://designatedsites.naturalengland.org.uk/PDFsForWeb/Citation/1003212.pdf]"}]'::jsonb),
    ('234afaf4-4030-41f9-aac6-6378d375d157'::uuid, 'card_description', 'Many flint chippings were found around this Late Neolithic dolmen. The chippings suggest the area was used to make flint items, and of several dolmens found nearby, only this one survives.', 'The Late Neolithic Anta das Pedras Grandes is the only surviving dolmen in its immediate area. Around it lay many flint chippings, suggesting that flint items were once made here.', 'teaser-card-s046-rollback:234afaf4-4030-41f9-aac6-6378d375d157:card_description', 'rollback of teaser-card-s046: card_description ''The Late Neolithic Anta das Pedras Grandes is the only surviving dolmen in its immediate area. Around it lay many flint chippings, suggesting that flint items were once made here.'' restored on Anta das Pedras Grandes', '3d9d8b26dd23bf6331520a812d6e793129598319b85732727e85b4c7c39876ab|c9f24248c200b46e76288446e7f5d5f65a8354c3bc8f446f6ae8da83368450be|c9f24248c200b46e76288446e7f5d5f65a8354c3bc8f446f6ae8da83368450be', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-rewrite1-001", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Many flint chippings were found around this Late Neolithic dolmen. The chippings suggest the area was used to make flint items, and of several dolmens found nearby, only this one survives."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check1-001 (check1), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "many flint chippings were found in the surrounding area [S2]; the site is a Late Neolithic dolmen [S1]; the chippings suggest the area was used to make flint items [S2]; several dolmens were found in the immediate area [S4]; only this one survives [S4]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify-007 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Many flint chippings were found around this dolmen [SUPPORTED: https://arqueologia.patrimoniocultural.pt/index.php?sid=visitaveis&subsid=47925]; The dolmen is Late Neolithic [SUPPORTED: https://arqueologia.patrimoniocultural.pt/index.php?sid=visitaveis&subsid=47925]; The chippings suggest the area was used to make flint items [SUPPORTED: https://arqueologia.patrimoniocultural.pt/index.php?sid=visitaveis&subsid=47925]; Several dolmens were found nearby [SUPPORTED: https://www.cm-odivelas.pt/autarquia/contactos/espacos-de-cultura-e-desporto/poi/nucleo-museologico-da-anta-das-pedras-grandes-98]; Of the several dolmens found nearby, only this one survives [SUPPORTED: https://www.cm-odivelas.pt/autarquia/contactos/espacos-de-cultura-e-desporto/poi/nucleo-museologico-da-anta-das-pedras-grandes-98]"}]'::jsonb),
    ('262b6a28-de86-4e63-bdba-398a67236618'::uuid, 'card_description', 'The 24 upright stones of this circle are probably only half the original number. Most had once fallen, and a trial dig is said to have yielded a little charcoal and one rough flint flake.', 'On Dartmoor, Brisworthy Stone Circle keeps 24 broad, low stones in a slight oval, probably only half the original number. A trial dig is said to have yielded charcoal and one flint flake.', 'teaser-card-s046-rollback:262b6a28-de86-4e63-bdba-398a67236618:card_description', 'rollback of teaser-card-s046: card_description ''On Dartmoor, Brisworthy Stone Circle keeps 24 broad, low stones in a slight oval, probably only half the original number. A trial dig is said to have yielded charcoal and one flint flake.'' restored on Brisworthy Stone Circle', 'fae41071201c79d705cc0e59714590caa88724cef7e46380b70e9f8cd3fb2231|80aace928e3381ca9e53527a7b8bef5e5a773becef61df85d75529cd844bf4d9|80aace928e3381ca9e53527a7b8bef5e5a773becef61df85d75529cd844bf4d9', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-rewrite1-001", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "The 24 upright stones of this circle are probably only half the original number. Most had once fallen, and a trial dig is said to have yielded a little charcoal and one rough flint flake."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check1-001 (check1), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "the circle has 24 upright stones [S5]; this is probably only half the original number [S5]; most of the stones had at one time fallen [S7]; a trial excavation is said to have yielded a small amount of charcoal [S8]; it is said to have yielded one rough flint flake [S8]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify-007 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "This circle has 24 upright stones [SUPPORTED: http://www.dartmoorwalks.org.uk/site/brisworthy.php]; The 24 upright stones are probably only half the original number [SUPPORTED: http://www.dartmoorwalks.org.uk/site/brisworthy.php]; Most of the stones had once fallen [SUPPORTED: http://www.dartmoorwalks.org.uk/site/brisworthy.php]; A trial dig is said to have been made at the circle [SUPPORTED: http://www.dartmoorwalks.org.uk/site/brisworthy.php]; The trial dig is said to have yielded a little charcoal [SUPPORTED: http://www.dartmoorwalks.org.uk/site/brisworthy.php]; The trial dig is said to have yielded one rough flint flake [SUPPORTED: http://www.dartmoorwalks.org.uk/site/brisworthy.php]"}]'::jsonb),
    ('29651376-c3fa-484e-b3bd-a6a64e97d0c6'::uuid, 'card_description', 'Curled-up toes tip the shoes of two gods carved into this Hittite cliff. The pair wear pointed horned hats, a sign of divinity, and walk with swords in their belts toward a seated goddess.', 'Hittite Empire rock carvings depicting three deities in pointed horned hats — signs of divinity. Two armed male figures with swords stride toward a seated goddess on a natural hilltop.', 'teaser-card-s046-rollback:29651376-c3fa-484e-b3bd-a6a64e97d0c6:card_description', 'rollback of teaser-card-s046: card_description ''Hittite Empire rock carvings depicting three deities in pointed horned hats — signs of divinity. Two armed male figures with swords stride toward a seated goddess on a natural hilltop.'' restored on Gavur Kalesi', 'ebd59ecccc434c9c8f4ab203f95dca0666f2d5a6d56d43d0ab4645c925745f81|4f4570cda702a32018c569ca17712b2699574ad06ebb737673be87a7baeb12fa|4f4570cda702a32018c569ca17712b2699574ad06ebb737673be87a7baeb12fa', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-rewrite2-001", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Curled-up toes tip the shoes of two gods carved into this Hittite cliff. The pair wear pointed horned hats, a sign of divinity, and walk with swords in their belts toward a seated goddess."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check2-001 (check2), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "two gods are carved into a cliff [S1, S2]; the carving is Hittite [S1]; the two gods wear shoes with curled-up toes [S2]; the two gods wear pointed horned hats [S2]; the horned hats are a sign of divinity [S2]; the two gods carry swords in their belts [S2]; the two gods walk toward a seated goddess [S2]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify-008 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Two gods carved into this cliff walk toward a seated goddess [SUPPORTED: https://vici.org/vici/20482/]; The carvings in the cliff are Hittite [SUPPORTED: https://www.hittitemonuments.com/gavurkale/]; The figures are carved into the rock [SUPPORTED: https://www.hittitemonuments.com/gavurkale/]; Curled-up toes tip the shoes of the two gods [SUPPORTED: https://vici.org/vici/20482/]; The pair wear pointed hats [SUPPORTED: https://vici.org/vici/20482/]; The hats are horned [SUPPORTED: https://vici.org/vici/20482/]; The horned hats are a sign of divinity [SUPPORTED: https://www.hittitemonuments.com/gavurkale/]; The two gods walk [SUPPORTED: https://www.hittitemonuments.com/gavurkale/]; The two gods have swords in their belts [SUPPORTED: https://www.hittitemonuments.com/gavurkale/]"}]'::jsonb),
    ('29f84776-1d97-4e09-ad40-95ea6e2d7247'::uuid, 'card_description', 'People camped here twenty-six thousand six hundred to thirty-two thousand years ago. The small Aboriginal hunting camp on a salty lake is one of the region''s earliest known occupied sites.', 'Aboriginal hunting camp on the shores of Lake Tyrrell with radiocarbon dates of 24,600–33,000 BC — among the earliest known occupation evidence between the Murray River and the mallee.', 'teaser-card-s046-rollback:29f84776-1d97-4e09-ad40-95ea6e2d7247:card_description', 'rollback of teaser-card-s046: card_description ''Aboriginal hunting camp on the shores of Lake Tyrrell with radiocarbon dates of 24,600–33,000 BC — among the earliest known occupation evidence between the Murray River and the mallee.'' restored on Box Gully Archaeological Site', 'cb451a9c8c042e01e1c721f7e1e97245dded3ecfed036f5ad2cde12ae2fda1e5|cdcacd9ffdbe7a989fc1c968d4cce1e427f6f69a3706bb07df9206c128011572|cdcacd9ffdbe7a989fc1c968d4cce1e427f6f69a3706bb07df9206c128011572', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-rewrite1-001", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "People camped here twenty-six thousand six hundred to thirty-two thousand years ago. The small Aboriginal hunting camp on a salty lake is one of the region''s earliest known occupied sites."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check1-001 (check1), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "people camped here 26,600 to 32,000 years ago (radiocarbon dates of the camp) [S2]; it was a small hunting camp [S2]; it is an Aboriginal site [S1]; it lies on a saline lake [S1]; it is one of the region''s earliest known occupied sites [S2]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify-008 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "People camped here twenty-six thousand six hundred to thirty-two thousand years ago [SUPPORTED: https://austhrutime.com/box_gully_occupation_south_murray_river_before_lgm.htm]; It was a small camp [SUPPORTED: https://austhrutime.com/box_gully_occupation_south_murray_river_before_lgm.htm]; It was a hunting camp [SUPPORTED: https://austhrutime.com/box_gully_occupation_south_murray_river_before_lgm.htm]; It was an Aboriginal camp [SUPPORTED: https://austhrutime.com/box_gully_occupation_south_murray_river_before_lgm.htm]; The camp is on a lake [SUPPORTED: https://austhrutime.com/box_gully_occupation_south_murray_river_before_lgm.htm]; The lake is salty [SUPPORTED: https://en.wikipedia.org/wiki/Lake_Tyrrell]; It is one of the region''s earliest known occupied sites [SUPPORTED: https://austhrutime.com/box_gully_occupation_south_murray_river_before_lgm.htm]"}]'::jsonb),
    ('2b2d0e62-5cbc-4427-be06-542064fb5076'::uuid, 'card_description', 'Not on the usual ridge or hilltop, these barrows lie on relatively low-lying ground. Most of the Bronze Age round barrows sit south of a road, a few north of it, near the head of a valley.', 'Not on a ridge but on low-lying ground near the head of a valley lie the Bronze Age round barrows of Poor Lot Barrow Cemetery, from about 1500 BC. From a minor plateau, all can be seen.', 'teaser-card-s046-rollback:2b2d0e62-5cbc-4427-be06-542064fb5076:card_description', 'rollback of teaser-card-s046: card_description ''Not on a ridge but on low-lying ground near the head of a valley lie the Bronze Age round barrows of Poor Lot Barrow Cemetery, from about 1500 BC. From a minor plateau, all can be seen.'' restored on Poor Lot Barrow Cemetery', 'c4f6fb10e1dacb53fab403364266979d482ce8d36fb4d54d59e8b1a8f1f27672|ef7c90b83f76fb50ef23dcc0fb25d9a80fa2ce5ad17df8ebb55ecb7dc48f0911|ef7c90b83f76fb50ef23dcc0fb25d9a80fa2ce5ad17df8ebb55ecb7dc48f0911', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-rewrite1-002", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Not on the usual ridge or hilltop, these barrows lie on relatively low-lying ground. Most of the Bronze Age round barrows sit south of a road, a few north of it, near the head of a valley."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check1-002 (check1), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "the site is a group of barrows [S1]; the barrows are not on a ridge or hilltop [S2]; a ridge or hilltop is the usual setting for barrows [S2]; the barrows lie on relatively low-lying ground [S2]; they are Bronze Age round barrows [S1]; most of the barrows are south of a road [S3]; a few are north of the road [S3]; they are near the head of a valley [S2]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify-008 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "These barrows lie not on the usual ridge or hilltop [SUPPORTED: https://www.english-heritage.org.uk/visit/places/winterbourne-poor-lot-barrows/history/]; A ridge or hilltop is the usual setting of such barrows [SUPPORTED: https://www.english-heritage.org.uk/visit/places/winterbourne-poor-lot-barrows/history/]; These barrows lie on relatively low-lying ground [SUPPORTED: https://www.british-history.ac.uk/rchme/dorset/vol2/pp434-480]; They are Bronze Age barrows [SUPPORTED: https://www.english-heritage.org.uk/visit/places/winterbourne-poor-lot-barrows/]; They are round barrows [SUPPORTED: https://www.english-heritage.org.uk/visit/places/winterbourne-poor-lot-barrows/history/]; Most of the barrows sit south of a road [SUPPORTED: https://www.komoot.com/highlight/3104565]; A few of the barrows sit north of the road [SUPPORTED: https://www.megalithic.co.uk/article.php?sid=4669]; The barrows lie near the head of a valley [SUPPORTED: https://www.british-history.ac.uk/rchme/dorset/vol2/pp434-480]"}]'::jsonb),
    ('306dfb7e-3a81-4a74-9a84-e53e6147d58b'::uuid, 'card_description', 'Christians turned a Neolithic dolmen into a chapel with a bell tower. Seven huge standing stones carry the dolmen''s massive capstone, and an altar wears 18th-century tiles from Lisbon.', 'A Neolithic dolmen transformed into a chapel dedicated to Sao Dinis in the 17th century. The ancient stone tomb became the altar of a Christian place of worship.', 'teaser-card-s046-rollback:306dfb7e-3a81-4a74-9a84-e53e6147d58b:card_description', 'rollback of teaser-card-s046: card_description ''A Neolithic dolmen transformed into a chapel dedicated to Sao Dinis in the 17th century. The ancient stone tomb became the altar of a Christian place of worship.'' restored on Capela de São Dinis', '22351f30c5ce86a8fe5322c87b1e0fd2f3514fbd448651fbe2cd5012b6b7eaaa|c304d11bc5ddb12d8cd7054337da54e0f99781c5cd55f97bdb08fec2b7af7028|c304d11bc5ddb12d8cd7054337da54e0f99781c5cd55f97bdb08fec2b7af7028', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-write-005", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Christians turned a Neolithic dolmen into a chapel with a bell tower. Seven huge standing stones carry the dolmen''s massive capstone, and an altar wears 18th-century tiles from Lisbon."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-005 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "a Neolithic dolmen was converted into a Christian chapel [S1, S2]; the chapel has a bell tower [S2]; seven huge orthostats (standing stones) carry the capstone [S1]; the capstone is massive [S1]; an altar is decorated with 18th-century tiles [S2]; the tiles come from Lisbon [S2]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify-009 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Christians turned a dolmen into a chapel. [SUPPORTED: https://arqueologia.patrimoniocultural.pt/index.php?sid=sitios&subsid=53934]; The dolmen is Neolithic. [SUPPORTED: https://arqueologia.patrimoniocultural.pt/index.php?sid=sitios&subsid=53934]; The chapel has a bell tower. [SUPPORTED: https://arqueologia.patrimoniocultural.pt/index.php?sid=sitios&subsid=53934]; Seven huge standing stones carry the dolmen''s capstone. [SUPPORTED: https://arqueologia.patrimoniocultural.pt/index.php?sid=sitios&subsid=53934]; The dolmen''s capstone is massive. [SUPPORTED: https://arqueologia.patrimoniocultural.pt/index.php?sid=sitios&subsid=53934]; An altar wears tiles. [SUPPORTED: https://arqueologia.patrimoniocultural.pt/index.php?sid=sitios&subsid=53934]; The altar tiles are from the 18th century. [SUPPORTED: https://repositorio.ulisboa.pt/server/api/core/bitstreams/8bad16bf-9d34-4849-9056-0b07c1b33812/content]; The altar tiles are from Lisbon. [SUPPORTED: https://repositorio.ulisboa.pt/server/api/core/bitstreams/8bad16bf-9d34-4849-9056-0b07c1b33812/content]"}]'::jsonb),
    ('32008339-d027-4578-b76a-915e5464f6c0'::uuid, 'card_description', 'A road built in the early 20th century cut through the courtyard of this Roman villa. North of the road, the manor house held the largest group of mosaics identified in the Lisbon region.', 'Roman ruins from the 3rd–5th century AD with structural elements deemed worthy of preservation. The villa was part of a larger agricultural estate.', 'teaser-card-s046-rollback:32008339-d027-4578-b76a-915e5464f6c0:card_description', 'rollback of teaser-card-s046: card_description ''Roman ruins from the 3rd–5th century AD with structural elements deemed worthy of preservation. The villa was part of a larger agricultural estate.'' restored on Roman Villa of Santo André de Almoçageme', 'dc9d3dc28933e24a2720eb29d72e30a49cca35c15841e79f233cd70e510380b5|ea599d910c05540a453819fa0225d5b5fdd382bdebfeebee2336dcde79feded2|ea599d910c05540a453819fa0225d5b5fdd382bdebfeebee2336dcde79feded2', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-write-005", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "A road built in the early 20th century cut through the courtyard of this Roman villa. North of the road, the manor house held the largest group of mosaics identified in the Lisbon region."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-005 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "a road was built in the early 20th century [S2]; the road cut through the villa''s courtyard (peristyle) [S2]; the site is a Roman villa [S1]; the manor house lies north of the road [S2]; the manor house held the largest group of mosaics identified in the Lisbon region [S3]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify-009 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "A road cut through the courtyard of this Roman villa. [SUPPORTED: https://lisboaromana.pt/en/place/roman-villa-of-santo-andre-de-almocageme]; The road was built in the early 20th century. [SUPPORTED: https://lisboaromana.pt/en/place/roman-villa-of-santo-andre-de-almocageme]; It is a Roman villa. [SUPPORTED: https://lisboaromana.pt/en/place/roman-villa-of-santo-andre-de-almocageme]; The manor house lay north of the road. [SUPPORTED: https://lisboaromana.pt/en/place/roman-villa-of-santo-andre-de-almocageme]; The manor house held mosaics. [SUPPORTED: https://lisboaromana.pt/en/place/roman-villa-of-santo-andre-de-almocageme]; The manor house held the largest group of mosaics identified in the Lisbon region. [SUPPORTED: https://lisboaromana.pt/en/place/roman-villa-of-santo-andre-de-almocageme]"}]'::jsonb),
    ('33e2399e-fd68-4aab-bf79-c5695a6c0bf0'::uuid, 'card_description', 'The Quechua word for inn and an ethnic group may both lie behind this site''s name. In 2002 the site, in a community of the same name, was declared a National Cultural Heritage.', 'Its name possibly joins the Tarma, an ethnic group, with the Quechua word tampu, an inn: Tarmatambo, an archaeological site in the Junín Region, declared National Cultural Heritage in 2002.', 'teaser-card-s046-rollback:33e2399e-fd68-4aab-bf79-c5695a6c0bf0:card_description', 'rollback of teaser-card-s046: card_description ''Its name possibly joins the Tarma, an ethnic group, with the Quechua word tampu, an inn: Tarmatambo, an archaeological site in the Junín Region, declared National Cultural Heritage in 2002.'' restored on Tarmatambo', 'e4416de8fea352a697ec01cecafc3e42a6492c3e449f5851b9ad2ac5aec35993|3924e8ae74b500957319a185dbe22ef2cc15192a6ffd31ca62cc54270d5e7b36|3924e8ae74b500957319a185dbe22ef2cc15192a6ffd31ca62cc54270d5e7b36', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-rewrite1-002", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "The Quechua word for inn and an ethnic group may both lie behind this site''s name. In 2002 the site, in a community of the same name, was declared a National Cultural Heritage."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check1-002 (check1), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "the site''s name may come from the Quechua word for inn [S1]; the site''s name may come from an ethnic group [S1]; the site lies in a community of the same name [S2]; in 2002 the site was declared a National Cultural Heritage [S3]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify-010 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "The site (Tarmatambo, Peru) was declared a National Cultural Heritage. [SUPPORTED: https://consultaprevia.cultura.gob.pe/sites/default/files/procesos/archivos/Expediente%20T%C3%A9cnico%20BIP%20Tarmatambo.pdf]; The declaration as National Cultural Heritage was made in 2002. [SUPPORTED: https://consultaprevia.cultura.gob.pe/sites/default/files/procesos/archivos/Expediente%20T%C3%A9cnico%20BIP%20Tarmatambo.pdf]; The site lies in a community of the same name. [SUPPORTED: https://www.turismoperuano.com/complejo-arqueologico-de-tarmatambo-junin]; The Quechua word for inn may lie behind the site''s name. [SUPPORTED: https://es.wikipedia.org/wiki/Tarmatambo_(localidad)]; The Quechua word in question (tampu) means inn. [SUPPORTED: https://en.wikipedia.org/wiki/Tambo_(Inca_structure)]; An ethnic group may also lie behind the site''s name. [SUPPORTED: https://huacasdelperu.org.pe/tarmatambo.html]"}]'::jsonb),
    ('398c3ef8-56c3-4640-a28a-ebaa8a36df33'::uuid, 'card_description', 'Two earthenware pots buried on this hill held hoards of Roman coins. With the coins, dated between AD 337 and AD 408, lay six silver rings and the remains of a glass vessel.', 'Banks reinforce the downland spur of Ebsbury, a possible hill fort. Buried in two earthenware pots lay Roman coins from between AD 337 and AD 408, found with six silver rings.', 'teaser-card-s046-rollback:398c3ef8-56c3-4640-a28a-ebaa8a36df33:card_description', 'rollback of teaser-card-s046: card_description ''Banks reinforce the downland spur of Ebsbury, a possible hill fort. Buried in two earthenware pots lay Roman coins from between AD 337 and AD 408, found with six silver rings.'' restored on Ebsbury', '7e037a0be0a7d8f5100949c5b9a88d206c2c8cc4b8f708d9c87774852174e422|3a4ff320730f95d239b88b9ed12f31cf9ff3b9e455d8ecdf1a183aaf08402301|3a4ff320730f95d239b88b9ed12f31cf9ff3b9e455d8ecdf1a183aaf08402301', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-write-006", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Two earthenware pots buried on this hill held hoards of Roman coins. With the coins, dated between AD 337 and AD 408, lay six silver rings and the remains of a glass vessel."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-006 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "the site is on a hill [S2]; two earthenware pots were found buried [S7]; the pots held hoards of Roman coins [S6, S7]; the coins date between AD 337 and AD 408 [S7]; six silver rings were found with the coins [S7]; remains of a glass vessel were found with the coins [S7]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify-011 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Hoards of Roman coins were found buried on this hill [SUPPORTED: https://hillforts.arch.ox.ac.uk/records/EN0427.html]; The coin hoards were held in two earthenware pots [SUPPORTED: https://hillforts.arch.ox.ac.uk/records/EN0427.html]; The coins date from AD 337 at the earliest [SUPPORTED: https://hillforts.arch.ox.ac.uk/records/EN0427.html]; The coins date to AD 408 at the latest [SUPPORTED: https://hillforts.arch.ox.ac.uk/records/EN0427.html]; Six silver rings lay with the coins [SUPPORTED: https://hillforts.arch.ox.ac.uk/records/EN0427.html]; The remains of a glass vessel lay with the coins [SUPPORTED: https://hillforts.arch.ox.ac.uk/records/EN0427.html]"}]'::jsonb),
    ('39927155-7597-4da8-9e3f-8c02d3d7a6ac'::uuid, 'card_description', 'Abstract engravings with Amazonian origins mark this large monolith. The carvings are possibly linked to beliefs about the cosmos and may be the work of ancestors of the Huachipaeri people.', 'Amazonian petroglyphs on a giant monolith in the Cusco highlands. Abstract spirals and a shape resembling a key may record ayahuasca visions; the carvings have clear Amazonian cultural origins.', 'teaser-card-s046-rollback:39927155-7597-4da8-9e3f-8c02d3d7a6ac:card_description', 'rollback of teaser-card-s046: card_description ''Amazonian petroglyphs on a giant monolith in the Cusco highlands. Abstract spirals and a shape resembling a key may record ayahuasca visions; the carvings have clear Amazonian cultural origins.'' restored on Jinkiori', '3919d50fab59998eb55214df540c6caa8ed59931e6b30bec3b92acb23673fc59|8e07e0beef6fcae19c0c406d907b4931867b0a26efd37265fb5b7fbc534f8750|8e07e0beef6fcae19c0c406d907b4931867b0a26efd37265fb5b7fbc534f8750', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-rewrite-v-003", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Abstract engravings with Amazonian origins mark this large monolith. The carvings are possibly linked to beliefs about the cosmos and may be the work of ancestors of the Huachipaeri people."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-v-003 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "the monolith carries abstract engravings [S2]; the engravings have Amazonian origins [S2]; the site centres on a large monolith [S1]; the abstract carvings are possibly linked to cosmological beliefs [S2]; the carvings may have been made by ancestors of the Huachipaeri [S3]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify2-003 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Engravings mark this monolith (petroglyphs engraved on one big rock) [SUPPORTED: http://www.rupestreweb.info/hinkiori.html]; The monolith is large [SUPPORTED: http://www.rupestreweb.info/hinkiori.html]; The engravings are abstract [SUPPORTED: http://www.rupestreweb.info/hinkiori.html]; The engravings have Amazonian origins [SUPPORTED: http://www.rupestreweb.info/hinkiori.html]; The carvings are possibly linked to beliefs about the cosmos [SUPPORTED: http://www.rupestreweb.info/hinkiori.html]; The carvings may be the work of ancestors of the Huachipaeri people [SUPPORTED: https://tardecroaste.wordpress.com/2011/03/18/el-enigmatico-monolito-de-jinkiori/]"}]'::jsonb),
    ('3a75476c-410d-4a37-9858-b0733fc6965d'::uuid, 'card_description', 'Towers for the dead stand with round houses on this fortified hilltop. The major Lupaca settlement emerged after the collapse of Tiwanaku, and farming terraces are among its features.', NULL, 'teaser-card-s046-rollback:3a75476c-410d-4a37-9858-b0733fc6965d:card_description', 'rollback of teaser-card-s046: card_description None restored on Tanqa Tanqa', '878294f160385429510dee70cef9edb2e38917b242568619982fc9db613e667e|17dd4224bcf37a0ad6a051e0bf9756bae827f605924e1f3a0d1c119d617e418c|17dd4224bcf37a0ad6a051e0bf9756bae827f605924e1f3a0d1c119d617e418c', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-rewrite-v-003", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Towers for the dead stand with round houses on this fortified hilltop. The major Lupaca settlement emerged after the collapse of Tiwanaku, and farming terraces are among its features."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-v-003 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "the site has funerary towers [S3]; the site has circular houses [S3]; it is a fortified hilltop settlement [S1]; it is a major settlement [S1]; it belongs to the Lupaca culture [S1]; it emerged after the collapse of Tiwanaku [S2]; agricultural terraces are among its features [S3]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify2-003 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Towers for the dead stand on this fortified hilltop [SUPPORTED: http://www.rupestreweb.info/chosecane.html]; Round houses stand on the site with the towers [SUPPORTED: https://revistas.cultura.gob.pe/index.php/arqueologicas/article/download/114/98/324]; The site is fortified [SUPPORTED: http://www.rupestreweb.info/chosecane.html]; The site is on a hilltop [SUPPORTED: http://www.rupestreweb.info/chosecane.html]; It is a major Lupaca settlement [SUPPORTED: https://revistas.cultura.gob.pe/index.php/arqueologicas/article/download/114/98/324]; The settlement emerged after the collapse of Tiwanaku [SUPPORTED: http://www.rupestreweb.info/chosecane.html]; Farming terraces are among its features [SUPPORTED: http://www.rupestreweb.info/chosecane.html]"}]'::jsonb),
    ('3bcff938-2352-4ea8-872f-3655fb444c87'::uuid, 'card_description', 'Stones set like the slices of a cake hold up a large capstone here. Eight men arranged them that way in 1866, a bad restoration of a Neolithic burial chamber at the head of a dry valley.', 'The chamber was badly restored in 1866 when eight men re-erected the stones, arranging them radially "rather like the slices of a cake" and supporting a large capstone.', 'teaser-card-s046-rollback:3bcff938-2352-4ea8-872f-3655fb444c87:card_description', 'rollback of teaser-card-s046: card_description ''The chamber was badly restored in 1866 when eight men re-erected the stones, arranging them radially "rather like the slices of a cake" and supporting a large capstone.'' restored on Hell Stone', '701ebd3d5962882d00d8eac3edca57eb9670eb5da92c334a19997746edb1000c|1434b90ebb70cf529e30d23570340b9cff3820d47f4fbb7ec4ccd1f51f4d9b46|1434b90ebb70cf529e30d23570340b9cff3820d47f4fbb7ec4ccd1f51f4d9b46', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-write-006", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Stones set like the slices of a cake hold up a large capstone here. Eight men arranged them that way in 1866, a bad restoration of a Neolithic burial chamber at the head of a dry valley."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-006 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "the stones are arranged like slices of a cake [S7]; the stones support a large capstone [S7]; eight men arranged the stones that way [S7]; this happened in 1866 [S7]; it was a bad restoration [S1, S7]; it is a Neolithic burial chamber [S1, S4]; it lies at the head of a dry valley [S3]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify-011 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Stones here are set like the slices of a cake [SUPPORTED: https://www.geograph.org.uk/photo/4308379]; The stones hold up a large capstone [SUPPORTED: https://heritage.dorsetcouncil.gov.uk/Monument/MDO2040]; Eight men arranged them that way [SUPPORTED: https://heritage.dorsetcouncil.gov.uk/Monument/MDO2040]; The stones were arranged that way in 1866 [SUPPORTED: https://heritage.dorsetcouncil.gov.uk/Monument/MDO2040]; The arrangement is a bad restoration [SUPPORTED: https://heritage.dorsetcouncil.gov.uk/Monument/MDO2040]; It is a Neolithic burial chamber [SUPPORTED: https://heritage.dorsetcouncil.gov.uk/Monument/MDO2040]; It lies at the head of a dry valley [SUPPORTED: https://heritage.dorsetcouncil.gov.uk/Monument/MDO2040]"}]'::jsonb),
    ('3d296ec1-adcb-43da-ae08-ffcdb378d4be'::uuid, 'card_description', 'Millennia of rain have grooved these three standing stones. In 2026, a study traced them to rocks about 11 miles west, and a stone cross with their fingerprint may be a fourth.', 'Grooved by millennia of rainfall, the three Devil''s Arrows stand in an almost straight line outside Boroughbridge. The tallest reaches 22.5 feet; the stones came from Brimham Rocks.', 'teaser-card-s046-rollback:3d296ec1-adcb-43da-ae08-ffcdb378d4be:card_description', 'rollback of teaser-card-s046: card_description "Grooved by millennia of rainfall, the three Devil''s Arrows stand in an almost straight line outside Boroughbridge. The tallest reaches 22.5 feet; the stones came from Brimham Rocks." restored on Devil''s Arrows', '6388d8f6ea42a484d2a26c7dbbbe83a6c29f57f207cd6600a7ed9b082d89d2be|6d1a4f8e35b05968620461340252c398dec61d4f2db0168ba1057876fad7dd7f|6d1a4f8e35b05968620461340252c398dec61d4f2db0168ba1057876fad7dd7f', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-write-006", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Millennia of rain have grooved these three standing stones. In 2026, a study traced them to rocks about 11 miles west, and a stone cross with their fingerprint may be a fourth."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-006 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "the stones are grooved by millennia of rainfall [S3]; there are three standing stones [S1]; a 2026 study traced the stones'' origin [S4]; they originated at rocks about 11 miles west [S4]; a stone cross has the same geological fingerprint [S5]; the cross may be a fourth stone of the monument [S5]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify-012 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Millennia of rain have grooved these standing stones (the Devil''s Arrows near Boroughbridge). [SUPPORTED: https://thejournalofantiquities.com/2012/05/27/devils-arrows-boroughbridge-north-yorkshire/]; There are three standing stones. [SUPPORTED: https://www.york.ac.uk/news-and-events/news/2026/research/neolithic-devils-arrow-stones-travelled-miles/]; In 2026, a study traced the stones to their source rocks. [SUPPORTED: https://www.york.ac.uk/news-and-events/news/2026/research/neolithic-devils-arrow-stones-travelled-miles/]; The source rocks lie about 11 miles west of the stones. [SUPPORTED: https://www.york.ac.uk/news-and-events/news/2026/research/neolithic-devils-arrow-stones-travelled-miles/]; A stone cross has the stones'' (geological) fingerprint. [SUPPORTED: https://www.york.ac.uk/news-and-events/news/2026/research/neolithic-devils-arrow-stones-travelled-miles/]; The stone cross may be a fourth stone of the monument. [SUPPORTED: https://www.york.ac.uk/news-and-events/news/2026/research/neolithic-devils-arrow-stones-travelled-miles/]"}]'::jsonb),
    ('3dd6b568-007f-4a95-877b-12324e031893'::uuid, 'card_description', 'Grindstone, carved stone, cheek: the Quechua words in this name can mean all three. The words also mean cobblestone, and the site lies at a section of the Qhapaq Ñan, the Inca road system.', 'Along a section of the Qhapaq Ñan, the Inca road system, lies Maray Qalla in Peru''s Ancash Region. In Quechua, maray can mean grindstone and qalla carved stone or cobblestone.', 'teaser-card-s046-rollback:3dd6b568-007f-4a95-877b-12324e031893:card_description', 'rollback of teaser-card-s046: card_description "Along a section of the Qhapaq Ñan, the Inca road system, lies Maray Qalla in Peru''s Ancash Region. In Quechua, maray can mean grindstone and qalla carved stone or cobblestone." restored on Maray Qalla', 'b51c4e7494479c4d57dc9244c021cdaca7d6d4af1d5827b059dd337c9e21d071|5a224c5dd4859f40abf2d7840a40d7d027f23969084aaff193bb9f61c6fde3cd|5a224c5dd4859f40abf2d7840a40d7d027f23969084aaff193bb9f61c6fde3cd', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-write-007", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Grindstone, carved stone, cheek: the Quechua words in this name can mean all three. The words also mean cobblestone, and the site lies at a section of the Qhapaq Ñan, the Inca road system."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-007 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "the site''s name is made of Quechua words [S1]; the words can mean grindstone [S1]; the words can mean carved stone [S1]; the words can mean cheek [S1]; the words can also mean cobblestone [S1]; the site lies at a section of the Qhapaq Nan [S3]; the Qhapaq Nan is the Inca road system [S3]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify-012 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "The Quechua words in this name (Maray Qalla) can mean grindstone. [SUPPORTED: https://futatraw.ourproject.org/descargas/DicQuechuaBolivia.pdf]; The site''s name is made of Quechua words. [SUPPORTED: https://es.wikipedia.org/wiki/Maraycalle]; The Quechua words in this name can mean carved stone. [SUPPORTED: https://futatraw.ourproject.org/descargas/DicQuechuaBolivia.pdf]; The Quechua words in this name can mean cheek. [SUPPORTED: https://futatraw.ourproject.org/descargas/DicQuechuaBolivia.pdf]; The words also mean cobblestone. [SUPPORTED: https://futatraw.ourproject.org/descargas/DicQuechuaBolivia.pdf]; The site lies at a section of the Qhapaq Ñan. [SUPPORTED: https://qhapaqnan.cultura.pe/sites/default/files/mi/archivo/SVA_ItinerarioCultural.pdf]; The Qhapaq Ñan is the Inca road system. [SUPPORTED: https://en.wikipedia.org/wiki/Inca_road_system]"}]'::jsonb),
    ('3e0ef472-929c-4669-ad45-c7a19c78d25f'::uuid, 'card_description', 'A Chinese pilgrim reported 1,400 monasteries in this valley. Remains of the Gandhara grave culture survive here, and an Italian mission digs at Barikot, identified as ancient Bazira.', 'Around 1000 BC. A 3,000-year corridor of Gandharan grave culture, Buddhist shrines, and Shahi-period ruins — stretching between Chakdara Bridge and Saidu Sharif in the Swat River valley.', 'teaser-card-s046-rollback:3e0ef472-929c-4669-ad45-c7a19c78d25f:card_description', 'rollback of teaser-card-s046: card_description ''Around 1000 BC. A 3,000-year corridor of Gandharan grave culture, Buddhist shrines, and Shahi-period ruins — stretching between Chakdara Bridge and Saidu Sharif in the Swat River valley.'' restored on Lower Swat Valley', '198d6e59a803d28c8be6d6eb429af9a6699f4b8b02d0764ff89dffb493e2a303|20e830a611c44fd36804e22ff4c2298fc5e1d93cc4bcbdb60d4d6cf1d3de3ae2|20e830a611c44fd36804e22ff4c2298fc5e1d93cc4bcbdb60d4d6cf1d3de3ae2', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-write-007", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "A Chinese pilgrim reported 1,400 monasteries in this valley. Remains of the Gandhara grave culture survive here, and an Italian mission digs at Barikot, identified as ancient Bazira."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-007 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "a Chinese pilgrim reported 1,400 monasteries in the valley [S3]; the site is a valley [S3]; remains of the Gandhara grave culture survive here [S2]; an Italian mission excavates at Barikot [S1]; Barikot is identified as ancient Bazira [S1]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify-012 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "A Chinese pilgrim (Xuanzang) reported 1,400 monasteries in this valley (the Swat valley). [SUPPORTED: https://www.wisdomlib.org/south-asia/book/buddhist-records-of-the-western-world-xuanzang/d/doc220203.html]; The reporter of the monasteries was a Chinese pilgrim. [SUPPORTED: https://www.carc.ox.ac.uk/PublicFiles/media/Geography%20of%20Gandharan%20Art%20published%20files/10_32028-9781789691863P41-57.pdf]; Remains of the Gandhara grave culture survive here. [SUPPORTED: https://en.wikipedia.org/wiki/Gandhara_grave_culture]; An Italian mission digs (is currently excavating) at Barikot. [SUPPORTED: https://www.unive.it/pag/44639/]; Barikot lies in this valley (Swat). [SUPPORTED: https://www.unive.it/pag/44639/]; Barikot is identified as ancient Bazira. [SUPPORTED: https://www.unive.it/pag/44639/]"}]'::jsonb),
    ('41eb7a6d-7eb0-4842-b25a-52cca7b3355e'::uuid, 'card_description', 'A burnt flint arrowhead lay among the finds of this stone tomb. Set on a natural outcrop, the ruined tomb would once have been covered by a mound or cairn, and now the capstone is cracked.', 'On a natural outcrop on Anglesey, the cracked capstone of Tŷ Newydd Burial Chamber rests on three uprights. In the chamber lay a hearth, flint flakes and a burnt flint arrowhead.', 'teaser-card-s046-rollback:41eb7a6d-7eb0-4842-b25a-52cca7b3355e:card_description', 'rollback of teaser-card-s046: card_description ''On a natural outcrop on Anglesey, the cracked capstone of Tŷ Newydd Burial Chamber rests on three uprights. In the chamber lay a hearth, flint flakes and a burnt flint arrowhead.'' restored on Tŷ Newydd Burial Chamber', '8fa553a09534b4dbdfaeb1092c35a47838bbc0c109be5b9b5f417c01f23e5101|c40482253ff9d2350edbb0c850c48b41abddc99b8d945c812d49104485b0b4cc|c40482253ff9d2350edbb0c850c48b41abddc99b8d945c812d49104485b0b4cc', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-write-007", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "A burnt flint arrowhead lay among the finds of this stone tomb. Set on a natural outcrop, the ruined tomb would once have been covered by a mound or cairn, and now the capstone is cracked."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-007 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "a burnt flint arrowhead was among the finds [S7]; the site is a stone tomb (megalithic dolmen / burial chamber) [S1, S2]; the tomb is set on a natural outcrop [S2]; the tomb is ruined [S2]; the tomb would originally have been covered by a mound or cairn [S2]; the capstone is cracked today [S4]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify-012 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "A burnt flint arrowhead lay among the finds of this tomb (Tŷ Newydd Burial Chamber). [SUPPORTED: https://thathistorycouple.co.uk/2025/02/24/ty-newydd-neolithic-cromlech-anglesey-wales/]; The tomb is a stone tomb. [SUPPORTED: https://coflein.gov.uk/en/sites/93834]; The tomb is set on a natural outcrop. [SUPPORTED: https://coflein.gov.uk/en/sites/93834]; The tomb is ruined. [SUPPORTED: https://coflein.gov.uk/en/sites/93834]; The tomb would once have been covered by a mound or cairn. [SUPPORTED: https://coflein.gov.uk/en/sites/93834]; The capstone is now cracked. [SUPPORTED: https://www.dailypost.co.uk/whats-on/neolithic-sites-visit-north-wales-13263214]"}]'::jsonb),
    ('4290304f-a120-40b4-bf61-9ebc7d52673c'::uuid, 'card_description', 'No roof shelters the columns of this hilltop temple. Built around 420 BC, the temple also lacks an inner room and was likely never completed, though the structure is well preserved.', 'Built around 420 BC on a hilltop above the ruined city of Segesta. A well-preserved Doric temple possibly by an Athenian architect — commissioned by the indigenous Elymians for reasons still debated.', 'teaser-card-s046-rollback:4290304f-a120-40b4-bf61-9ebc7d52673c:card_description', 'rollback of teaser-card-s046: card_description ''Built around 420 BC on a hilltop above the ruined city of Segesta. A well-preserved Doric temple possibly by an Athenian architect — commissioned by the indigenous Elymians for reasons still debated.'' restored on Temple of Segesta', 'ad408342d63b1d9be05fbcb5724fae06370317759b9f8a7390927b80c4112d0c|d7c7f17184627959e563c1baa835e4e373fa0a4ea8ecb9f38690fd2766226f68|d7c7f17184627959e563c1baa835e4e373fa0a4ea8ecb9f38690fd2766226f68', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-write-007", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "No roof shelters the columns of this hilltop temple. Built around 420 BC, the temple also lacks an inner room and was likely never completed, though the structure is well preserved."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-007 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "the temple has columns [S2]; the temple has no roof [S2]; the temple stands on a hilltop [S1]; it was built around 420 BC [S1]; the temple lacks an inner room (cella) [S2]; the temple was likely never completed [S2]; the structure is well preserved [S2]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify-012 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "No roof shelters the columns of this temple (the Doric temple of Segesta). [SUPPORTED: https://www.enjoysicilia.it/en/trapani-isole-egadi/segesta/tempio-segesta/]; The temple has (standing) columns. [SUPPORTED: https://www.enjoysicilia.it/en/trapani-isole-egadi/segesta/tempio-segesta/]; The temple stands on a hilltop. [SUPPORTED: https://www.lasiciliainrete.it/en/directory-tangibili/listing/tempio-dorico-di-segesta/]; The temple was built around 420 BC. [SUPPORTED: https://www.enjoysicilia.it/en/trapani-isole-egadi/segesta/tempio-segesta/]; The temple also lacks an inner room. [SUPPORTED: https://www.enjoysicilia.it/en/trapani-isole-egadi/segesta/tempio-segesta/]; The temple was likely never completed. [SUPPORTED: https://www.enjoysicilia.it/en/trapani-isole-egadi/segesta/tempio-segesta/]; The structure is well preserved. [SUPPORTED: https://www.enjoysicilia.it/en/trapani-isole-egadi/segesta/tempio-segesta/]"}]'::jsonb),
    ('42f11dde-ad7e-46e0-ab7b-37a7add49986'::uuid, 'card_description', 'The names of 60 tribes stood on the altar of this Roman sanctuary. Drusus founded the sanctuary where the Rhone and Saone rivers meet, and the site was consecrated to Roma and Augustus.', 'Drusus founded the Ara trium Galliarum at Lugdunum, where the Rhone and Saone meet, as a sanctuary to Roma and Augustus. Its altar bore the names of 60 Gallic tribes.', 'teaser-card-s046-rollback:42f11dde-ad7e-46e0-ab7b-37a7add49986:card_description', 'rollback of teaser-card-s046: card_description ''Drusus founded the Ara trium Galliarum at Lugdunum, where the Rhone and Saone meet, as a sanctuary to Roma and Augustus. Its altar bore the names of 60 Gallic tribes.'' restored on Ara trium Galliarum', 'eee2ee07cb3055c1d8833253260d48ea472dc0df913ff4dbb44c78d41b67e460|e8719b3ae3b7df58e5706c38ca1577687bbd52197e92ca6b90d87c33161744b4|e8719b3ae3b7df58e5706c38ca1577687bbd52197e92ca6b90d87c33161744b4', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-write-007", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "The names of 60 tribes stood on the altar of this Roman sanctuary. Drusus founded the sanctuary where the Rhone and Saone rivers meet, and the site was consecrated to Roma and Augustus."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-007 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "the altar bore the names of 60 tribes [S3]; the site was a Roman sanctuary with an altar [S1]; Drusus founded the sanctuary [S1]; the sanctuary lay at the confluence of the Rhone and Saone [S1]; it was consecrated to Roma and Augustus [S2]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify-013 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "The names of 60 tribes stood on the altar of this Roman sanctuary (the Ara trium Galliarum at Lugdunum, France). [SUPPORTED: https://penelope.uchicago.edu/Thayer/E/Roman/Texts/Strabo/4C*.html]; It was a Roman sanctuary. [SUPPORTED: https://fr.wikipedia.org/wiki/Sanctuaire_f%C3%A9d%C3%A9ral_des_Trois_Gaules]; Drusus founded the sanctuary. [SUPPORTED: https://fr.wikipedia.org/wiki/Sanctuaire_f%C3%A9d%C3%A9ral_des_Trois_Gaules]; Drusus founded the sanctuary where the Rhone and Saone rivers meet. [SUPPORTED: https://fr.wikipedia.org/wiki/Sanctuaire_f%C3%A9d%C3%A9ral_des_Trois_Gaules]; The site was consecrated to Roma and Augustus. [SUPPORTED: https://fr.wikipedia.org/wiki/Sanctuaire_f%C3%A9d%C3%A9ral_des_Trois_Gaules]"}]'::jsonb);

DO $$
DECLARE
    bad      INTEGER;
    moved    INTEGER := 0;
    expected INTEGER := 40;
    r        RECORD;
BEGIN
    -- expected is the plan's own row count, rendered here, and not a second count of the
    -- temp table the loop below iterates: counting the same table twice would make the
    -- comparison after the loop a tautology. The instance that makes a short loop
    -- unreachable is apply_remediation_change, which raises unless exactly one row
    -- matched; this guard is what reports a loop that changed fewer rows than the plan.

    -- scope guard 1: every planned row is a card_stats row of a curated site that still exists
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p LEFT JOIN card_stats t ON t.site_id = p.site_id
      LEFT JOIN unified_sites u ON u.id = p.site_id
     WHERE t.site_id IS NULL OR u.id IS NULL OR u.source_id <> 'ancient_nerds';
    IF bad > 0 THEN
        -- the source name is a RAISE argument, never part of the quoted message: a name
        -- spliced into the message text only parses while the name happens to contain no
        -- quote, which is a property of today's value and not of this code. G0's guard is
        -- the shape this one copies.
        RAISE EXCEPTION 'teaser card: % planned row(s) are not % sites', bad, 'ancient_nerds';
    END IF;

    -- scope guard 2: the plan is a set of real changes, each one writable in its column
    -- (compared in the column's own type; CASE, because only CASE fixes the order in
    -- which the casts are evaluated)
    SELECT count(*) INTO bad FROM _teaser_card_plan p
     WHERE p.new_value = '' OR CASE p.column_name
                WHEN 'card_description' THEN p.new_value::character varying IS NOT DISTINCT FROM p.old_value::character varying OR length(p.new_value) > 200
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) are not writable changes', bad;
    END IF;

    -- scope guard 3: every planned row still holds the old value the plan names
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p JOIN card_stats t ON t.site_id = p.site_id
     WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS DISTINCT FROM p.old_value::character varying
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) no longer hold the planned old value', bad;
    END IF;

    -- scope guard 5: every planned row still holds the input its value was derived from
    SELECT count(*) INTO bad
      FROM (SELECT DISTINCT site_id, premise FROM _teaser_card_plan) p JOIN unified_sites u ON u.id = p.site_id
     WHERE (coalesce(u.raw_data -> '_card_provenance' ->> 'text_sha256', '') || '|' || coalesce(u.raw_data -> '_card_provenance' ->> 'desc_sha256', '') || '|' || encode(sha256(convert_to(coalesce(u.description, ''), 'UTF8')), 'hex')) IS DISTINCT FROM p.premise;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) no longer hold the premise the plan derived its value from', bad;
    END IF;

    -- the only writer: the conditional UPDATE and its journal row commit together, and
    -- the function raises unless exactly one row matched
    FOR r IN SELECT * FROM _teaser_card_plan ORDER BY site_id, column_name LOOP
        moved := moved + apply_remediation_change(
            'card_stats', r.column_name, 'site_id', r.site_id::text,
            r.old_value, r.new_value,
            'WB/teaser-card', 'wb-teaser-card-s046-rollback', r.change_key, 'opus-checked', r.evidence, r.site_id);
    END LOOP;

    IF moved <> expected THEN
        RAISE EXCEPTION 'teaser card: % row(s) changed, % planned', moved, expected;
    END IF;

    -- invariant 1: every planned row now holds the new value
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p JOIN card_stats t ON t.site_id = p.site_id
     WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS DISTINCT FROM p.new_value::character varying
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) do not hold the new value', bad;
    END IF;

    -- invariant 2: the journal and the data agree, row for row, in both directions
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p LEFT JOIN remediation_change_log l
        ON l.row_pk = p.site_id::text AND l.table_name = 'card_stats'
       AND l.column_name = p.column_name
       AND l.run_stamp = 'wb-teaser-card-s046-rollback'
     WHERE l.id IS NULL
        OR l.new_value IS DISTINCT FROM p.new_value
        OR l.old_value IS DISTINCT FROM p.old_value;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) have no matching journal row', bad;
    END IF;

    SELECT count(*) INTO bad FROM remediation_change_log l
     WHERE l.run_stamp = 'wb-teaser-card-s046-rollback'
       AND (l.table_name <> 'card_stats' OR l.column_name NOT IN ('card_description'));
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: this run stamp journalled % row(s) outside card_stats.(card_description)', bad;
    END IF;

    RAISE NOTICE 'teaser card: % of % planned cell(s) changed and journalled over 40 curated site(s)',
        moved, expected;
END $$;

COMMIT;

-- Post-commit read: the numbers the report quotes, from the database, not from the plan.
SELECT 'journal rows for this run stamp' AS metric, count(*)::text AS value
  FROM remediation_change_log WHERE run_stamp = 'wb-teaser-card-s046-rollback'
UNION ALL
SELECT 'journal rows for this test id', count(*)::text
  FROM remediation_change_log WHERE test_id = 'WB/teaser-card'
UNION ALL
SELECT 'planned rows now holding the new value', count(*)::text
  FROM remediation_change_log l
 WHERE l.run_stamp = 'wb-teaser-card-s046-rollback' AND l.table_name = 'card_stats'
   AND l.column_name IN ('card_description')
   AND EXISTS (SELECT 1 FROM card_stats t
                WHERE t.site_id::text = l.row_pk AND CASE l.column_name
                WHEN 'card_description' THEN t.card_description IS NOT DISTINCT FROM l.new_value::character varying
                ELSE false END)
UNION ALL
SELECT 'curated sites whose teaser provenance does not hash their live card', count(*)::text
  FROM unified_sites
 WHERE source_id = 'ancient_nerds' AND raw_data ? '_card_provenance' AND NOT EXISTS (SELECT 1 FROM card_stats cs WHERE cs.site_id = unified_sites.id AND encode(sha256(convert_to(cs.card_description, 'UTF8')), 'hex') = unified_sites.raw_data -> '_card_provenance' ->> 'text_sha256')
UNION ALL
SELECT 'curated sites', count(*)::text
  FROM unified_sites WHERE source_id = 'ancient_nerds';
